package io.github.diodeme.ji.telemetry;

import java.util.List;
import java.util.Map;
import java.util.OptionalLong;

/** Detached deterministic diagnostic snapshot used by the adapter TCK. */
public record RecordedSpan(
        long spanId,
        OptionalLong parentSpanId,
        String name,
        Map<String, TelemetryValue> attributes,
        List<TelemetryEvent> events,
        List<MetricPoint> metrics,
        SpanStatus status,
        boolean settled,
        OptionalLong endSequence) {
    public RecordedSpan {
        attributes = Map.copyOf(attributes);
        events = List.copyOf(events);
        metrics = List.copyOf(metrics);
    }
}
